import Foundation
import XCTest
@testable import SideEditorCore

/// The checked-in fixture corpus, generated by
/// `Tests/Fixtures/generate_fixtures.py`.
///
/// Lookup goes through `#filePath` rather than a resource bundle: the tests run
/// from the package checkout in CI, and this keeps the package free of resource
/// declarations that would also have to be resolved inside the iOS app.
enum Fixture {
    static let directory: URL = {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures", isDirectory: true)
    }()

    static func url(_ name: String) -> URL {
        directory.appendingPathComponent(name)
    }

    static func data(_ name: String) throws -> Data {
        try Data(contentsOf: url(name))
    }

    static var allNames: [String] {
        let names = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
        return names.filter { $0.hasSuffix(".ipa") }.sorted()
    }

    static var validNames: [String] {
        allNames.filter { $0.hasPrefix("valid-") }
    }

    static var hostileNames: [String] {
        allNames.filter { !$0.hasPrefix("valid-") }
    }
}

/// Asserts that `expression` throws an `IPAError` matching `check`.
///
/// Written by hand instead of `XCTAssertThrowsError` because the corpus tests
/// report each fixture by name inside a loop, which needs a `XCTFail` that names
/// the fixture rather than one opaque assertion.
func expectIPAError<T>(
    _ expression: @autoclosure () throws -> T,
    _ check: (IPAError) -> Bool,
    _ label: String = "",
    file: StaticString = #filePath,
    line: UInt = #line
) {
    do {
        _ = try expression()
        XCTFail("expected an IPAError\(label.isEmpty ? "" : " (\(label))")", file: file, line: line)
    } catch let error as IPAError {
        XCTAssertTrue(
            check(error),
            "unexpected IPAError \(error)\(label.isEmpty ? "" : " (\(label))")",
            file: file,
            line: line
        )
    } catch {
        XCTFail(
            "expected an IPAError, got \(error)\(label.isEmpty ? "" : " (\(label))")",
            file: file,
            line: line
        )
    }
}

func makeSandbox() throws -> URL {
    let url = FileManager.default.temporaryDirectory
        .appendingPathComponent("SideEditorCoreTests-\(UUID().uuidString)", isDirectory: true)
    try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
    return url
}

enum Snapshot {
    /// Relative paths of everything under `root`, including directories.
    static func paths(under root: URL) -> [String] {
        let fileManager = FileManager.default
        guard let enumerator = fileManager.enumerator(
            at: root,
            includingPropertiesForKeys: nil,
            options: [],
            errorHandler: nil
        ) else {
            return []
        }
        let prefix = root.standardizedFileURL.path + "/"
        var paths: [String] = []
        for case let url as URL in enumerator {
            let path = url.standardizedFileURL.path
            if path.hasPrefix(prefix) {
                paths.append(String(path.dropFirst(prefix.count)))
            }
        }
        return paths.sorted()
    }
}

extension Data {
    static func repeated(_ byte: UInt8, count: Int) -> Data {
        Data([UInt8](repeating: byte, count: count))
    }
}
